def bestMeetingDistance(grid):
    rows, cols = [], []
    R, C = len(grid), len(grid[0])
    for i in range(R):
        for j in range(C):
            if grid[i][j] == 1:
                rows.append(i)
    for j in range(C):
        for i in range(R):
            if grid[i][j] == 1:
                cols.append(j)
    mr = rows[len(rows) // 2]
    mc = cols[len(cols) // 2]
    return sum(abs(r - mr) for r in rows) + sum(abs(c - mc) for c in cols)
